def cold_outlet_temperature(m_hot, cp_hot, Th_in, Th_out, m_cold, cp_cold, Tc_in, loss=0.0):
    Q_hot = m_hot * cp_hot * (Th_in - Th_out)     # W given up by the hot stream
    Q_cold = (1.0 - loss) * Q_hot                 # W that reaches the cold stream
    return Tc_in + Q_cold / (m_cold * cp_cold)
